-- 337 preguntas nuevas de los temas 12 y 13 (fichas de vehículos del SCIS: BUL, BUP, BPM, BRM, BRP, BNP, AEA y ABA).
-- Los 12 bloques-tabla del corpus no tenían ninguna pregunta: el generador original solo leía bloques con «texto».
-- Idempotente: no se tocan las que ya existan con el mismo id.
with ins as (
  on conflict (id) do nothing
  returning 1)
select 'vehículos: ' || count(*) || ' de 337 preguntas insertadas' as resultado from ins;
